# A \( written in a string, a comment or a backquoted name is not a lambda writing: ignored. fun3 <- eval(parse(text = "function(x){
    y <- "the \\(x) writing in a string" # a \(x) in a comment
    `\\(z)` <- 1
    x
}", keep.source = TRUE)) fun3 ## function(x){ ##     y <- "the \(x) writing in a string" # a \(x) in a comment ##     `\(z)` <- 1 ##     x ## } lambda_check(x = fun3) ##  ##  ## AFTER RUNNING saferDev::lambda_check(). ## INSIDE fun3(), EVERYTHING SEEMS CLEAN.

